# name: ca-contour-primitive-on-disc-test
# technique: test fallback; kernel instances: explicit primitives on discs
# goal: sage_test KaluzaKlein.ComplexAnalysis.CauchyTheorem.primitive_on_disc
# description: instances of primitive_on_disc (Contour integration, part I chapter 4), edge case first or marked
SEED = 0
t = var('t', domain='real')
z = var('z')
CB = ComplexBallField(128)
RI = RealIntervalField(128)
J = CB(0, 1)
def ex(e):
    return SR(e).rectform().simplify_full()
def pint(f, g, a, b):
    # the parametrised contour integral of f (an expression in z) along g(t), t in [a, b], exactly
    return integrate(f.subs(z=g) * diff(g, t), t, a, b)
def speed(g):
    d = diff(g, t)
    return sqrt(d.real_part() ** 2 + d.imag_part() ** 2).simplify_full()
def bint(F, a, b):
    # a rigorous ball enclosure of the integral of F (a function on balls) over [a, b]
    return CB.integral(lambda x, _: F(x), CB(a), CB(b))
def circ(F, c, R):
    # a rigorous ball enclosure of the circle integral of F over |z - c| = R
    return bint(lambda x: F(CB(c) + CB(R) * (J * x).exp()) * CB(R) * J * (J * x).exp(), 0, 2 * CB.pi())
def gap(*pairs):
    # an interval enclosing the sum of |x - y| over the pairs: it contains 0 when every pair agrees
    return sum(RI(abs(CB(x) - CB(y))) for x, y in pairs)
instances = [
  kernel_instance('Complex.exp', '0', '1', '(Complex.differentiable_exp.differentiableOn)',
                  proof='exact ⟨Complex.exp, fun z _ => Complex.hasDerivAt_exp z⟩'),
  kernel_instance('Complex.cos', '(1 + Complex.I)', '2', '(Complex.differentiable_cos.differentiableOn)',
                  proof='exact ⟨Complex.sin, fun z _ => Complex.hasDerivAt_sin z⟩'),
  kernel_instance('(fun w : ℂ => 2 * w)', '0', '0', '(by fun_prop)',
                  proof='exact ⟨fun w => w ^ 2, fun z _ => by simpa using hasDerivAt_pow 2 z⟩', edge=True)]
